using System.IO;
using System.Text;
using HeroCat.Bots.Policies;
using HeroCat.Runtime.Save;
using HeroCat.Sim.Content;
using Newtonsoft.Json;

namespace HeroCat.Bots.Golden
{
    /// <summary>
    /// src/HeroCat.Runtime.Tests/Fixtures/Saves/v1.json (02 section 7.3): a save body at v1 from a played bot profile,
    /// regenerated by `save-fixture --update` and drift-checked by check.sh until SaveSchema.V1Frozen. After the freeze
    /// the file is never regenerated and MigrationTests M5 pins its hash instead.
    /// </summary>
    public static class SaveFixture
    {
        public const string Regenerate = "dotnet run -c Release --project src/HeroCat.Bots -- save-fixture --update";
        public const ulong Seed = 7;
        public const int Days = 2;

        /// <summary>The repo's fixture path: src/ is a sibling of the content folder.</summary>
        public static string DefaultPath(string contentDir) =>
            Path.Combine(Path.GetDirectoryName(Path.GetFullPath(contentDir).TrimEnd('/', '\\')), "src", "HeroCat.Runtime.Tests",
                         "Fixtures", "Saves", "v1.json");

        public static string Generate(ContentDb db)
        {
            string body = null;
            var runner = new BotRunner(db)
            {
                AfterDay = (day, ctx) =>
                {
                    if (day != Days) return;
                    SaveSystem.Stamp(ctx.State, ctx.Clock.NowServerSeconds, db, HarnessConstants.BotDeviceId);
                    body = SaveSerializer.ToJson(ctx.State).ToString(Formatting.Indented).Replace("\r\n", "\n") + "\n";
                },
            };
            runner.Run(BotPolicies.Create("greedy-f2p"), Seed, Days);
            return body;
        }

        public static void Write(string path, string text)
        {
            Directory.CreateDirectory(Path.GetDirectoryName(path));
            File.WriteAllText(path, text, new UTF8Encoding(false));
        }
    }
}
